import React, { useEffect, useState } from 'react';
import {
  Box,
  Typography,
  TextField,
  IconButton,
  Divider,
  Button,
  Chip,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import PropTypes from 'prop-types';
import DeleteIcon from '@mui/icons-material/Delete';
import AutoFixHighIcon from '@mui/icons-material/AutoFixHigh';
import Tooltip from '@mui/material/Tooltip';
import Snackbar from '@mui/material/Snackbar';
import Alert from '@mui/material/Alert';
import FormControlLabel from '@mui/material/FormControlLabel';
import Checkbox from '@mui/material/Checkbox';
import Autocomplete from '@mui/material/Autocomplete';
import {
  getDuplicateMocks,
  isMockInDefaultMocks,
  convertToValidJSON,
  isValidJSON,
} from './utils/CommonUtils';
import { FtJSON } from './utils/FtJSON';
import AiEditDialog from './AiEditDialog';
import ResponseVariantsDialog from './ResponseVariantsDialog';

function parseMatchHeaderNames(raw) {
  if (!raw || typeof raw !== 'string') {
    return [];
  }
  const names = raw.split(',').map((h) => h.trim()).filter(Boolean);
  return [...new Set(names)];
}

function getHeaderValueCaseInsensitive(headers, headerName) {
  if (!headers || !headerName) {
    return undefined;
  }
  const lower = headerName.toLowerCase();
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === lower) {
      return headers[key];
    }
  }
  return undefined;
}

const MockDataView = ({
  envDetails,
  mockItem,
  onClose,
  selectedTest,
  onClickUpload,
  defaultMocks,
}) => {
  const [mockData, setMockData] = useState(mockItem);
  const [mockDataString, setMockDataString] = useState();
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState('');
  const [snackbarSeverity, setSnackbarSeverity] = useState('success');

  const showSnackbar = (message, severity = 'success') => {
    setSnackbarMessage(message);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };
  const [ipInputValue, setIpInputValue] = useState('');
  const [aiDialogOpen, setAiDialogOpen] = useState(false);
  const [variantsDialogOpen, setVariantsDialogOpen] = useState(false);
  const [variants, setVariants] = useState([]);
  const [variantsLoading, setVariantsLoading] = useState(false);
  const [variantsError, setVariantsError] = useState('');

  useEffect(() => {
    setMockDataString(FtJSON.stringify(mockData, null, 2));
  }, [mockData]);

  useEffect(() => {
    if (!mockItem) {
      return;
    }
    const nextMockData = { ...mockItem };
    if (!nextMockData.response) {
      nextMockData.response = { headers: {}, content: '', status: 200 };
    } else if (!nextMockData.response.headers) {
      nextMockData.response = {
        ...nextMockData.response,
        headers: {},
      };
    }
    try {
      const rawContent = nextMockData.response.content;
      nextMockData.response = {
        ...nextMockData.response,
        content: rawContent
          ? FtJSON.stringify(FtJSON.parse(rawContent), null, 2)
          : '',
      };
    } catch (e) {
      console.log(e);
    }
    setMockData(nextMockData);
  }, [mockItem]);

  const onDelete = async () => {
    const endpoint = selectedTest
      ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}?name=${selectedTest.name}`
      : `/api/v1/defaultmocks/${mockItem.id}`;
    await fetch(endpoint, {
      method: 'DELETE',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${localStorage.getItem('token')}`,
      },
    })
      .then((response) => {
        if (response.ok) {
          console.log('Mock data deleted successfully');
        } else {
          console.error('Failed to delete mock data');
        }
      })
      .catch((error) => {
        console.error('Error deleting mock data:', error);
      });
    onClose(true);
  };

  const deleteDuplicate = async (mock) => {
    const endpoint = selectedTest
      ? `/api/v1/tests/${selectedTest.id}/mockdata/${mock.id}?name=${selectedTest.name}`
      : `/api/v1/defaultmocks/${mock.id}`;
    try {
      const response = await fetch(endpoint, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
      });
      if (!response.ok) {
        console.error('Failed to delete mock data');
        return false;
      }
      console.log('Mock data deleted successfully');
      return true;
    } catch (error) {
      console.error('Error deleting mock data:', error);
      return false;
    }
  };

  const deleteAllDuplicates = async () => {
    const duplicates = getDuplicateMocks(selectedTest.mockData, mockItem);
    const results = await Promise.all(duplicates.map((mock) => deleteDuplicate(mock)));
    const allSucceeded = results.every(Boolean);
    showSnackbar(
      allSucceeded
        ? 'All duplicates deleted successfully'
        : 'Some duplicates failed to delete',
      allSucceeded ? 'success' : 'error'
    );
    onClose(true);
  };

  const onUpdate = async () => {
    const endpoint = selectedTest
      ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}?name=${selectedTest.name}`
      : `/api/v1/defaultmocks/${mockItem.id}`;
    try {
      const response = await fetch(endpoint, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: FtJSON.stringify(mockData),
      });

      if (response.ok) {
        console.log('Mock data updated successfully');
        showSnackbar('Mock data updated successfully');
      } else {
        console.error('Failed to update mock data');
        showSnackbar('Failed to update mock data', 'error');
      }
    } catch (error) {
      console.error('Error updating mock data:', error);
      showSnackbar('Error updating mock data', 'error');
    }
  };

  const onContentChange = (event) => {
    try {
      const parsedContent = convertToValidJSON(event.target.value);
      setMockData({
        ...mockData,
        response: { ...mockData.response, content: parsedContent },
      });
    } catch (error) {
      console.error('Invalid JSON content:', error);
    }
  };

  const onPostDataChange = (event) => {
    try {
      const parsedContent = convertToValidJSON(event.target.value);
      setMockData({
        ...mockData,
        request: { ...mockData.request, postData: { text: parsedContent } },
      });
    } catch (error) {
      console.error('Invalid JSON content:', error);
    }
  };

  const onDataChange = (event) => {
    try {
      setMockDataString(event.target.value);
      setMockData(FtJSON.parse(event.target.value));
    } catch (error) {
      console.error('Invalid JSON data:', error);
    }
  };

  const handleSnackbarClose = () => {
    setSnackbarOpen(false);
  };

  const handleAiSuccess = (updatedContent) => {
    setMockData({
      ...mockData,
      response: { ...mockData.response, content: updatedContent },
    });
  };

  const fetchVariants = async () => {
    if (!mockItem?.id) return;
    setVariantsLoading(true);
    setVariantsError('');
    try {
      const endpoint = selectedTest
        ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}/variants?name=${encodeURIComponent(selectedTest.name)}`
        : `/api/v1/defaultmocks/${mockItem.id}/variants`;
      const response = await fetch(endpoint, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
      });
      if (response.ok) {
        const data = await response.json();
        setVariants(Array.isArray(data) ? data : []);
      } else {
        setVariantsError('Failed to load variants');
        setVariants([]);
      }
    } catch (err) {
      setVariantsError(err.message || 'Failed to load variants');
      setVariants([]);
    } finally {
      setVariantsLoading(false);
    }
  };

  const handleOpenVariantsDialog = () => {
    setVariantsDialogOpen(true);
    fetchVariants();
  };

  const handleEnableVariants = async () => {
    if (!mockItem?.id) return;
    const responseContent = mockData?.response?.content ?? '';
    const variantId = `variant-${Date.now()}`;
    const initialVariants = [
      {
        id: variantId,
        name: 'Default',
        response: responseContent,
      },
    ];

    const endpoint = selectedTest
      ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}/variants?name=${encodeURIComponent(selectedTest.name)}`
      : `/api/v1/defaultmocks/${mockItem.id}/variants`;

    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: FtJSON.stringify({ variants: initialVariants }),
      });
      if (response.ok) {
        const updatedMock = {
          ...mockData,
          current_variant_id: variantId,
        };
        setMockData(updatedMock);

        const updateEndpoint = selectedTest
          ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}?name=${encodeURIComponent(selectedTest.name)}`
          : `/api/v1/defaultmocks/${mockItem.id}`;
        await fetch(updateEndpoint, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${localStorage.getItem('token')}`,
          },
          body: FtJSON.stringify(updatedMock),
        });

        await fetchVariants();
        showSnackbar('Variants enabled. Current response saved as Default variant.');
      } else {
        setVariantsError('Failed to enable variants');
      }
    } catch (err) {
      setVariantsError(err.message || 'Failed to enable variants');
    }
  };

  const handleAddVariant = async (variantName, responseContent) => {
    if (!mockItem?.id || !variantName?.trim()) return;
    const content =
      responseContent !== undefined && responseContent !== null
        ? (typeof responseContent === 'string'
            ? responseContent
            : FtJSON.stringify(responseContent))
        : typeof mockData?.response?.content === 'string'
          ? mockData.response.content
          : FtJSON.stringify(mockData?.response?.content ?? '');
    const variantId = `variant-${Date.now()}`;
    const newVariant = {
      id: variantId,
      name: variantName.trim(),
      response: content,
    };
    const updatedVariants = [...variants, newVariant];

    const endpoint = selectedTest
      ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}/variants?name=${encodeURIComponent(selectedTest.name)}`
      : `/api/v1/defaultmocks/${mockItem.id}/variants`;

    try {
      const response = await fetch(endpoint, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: FtJSON.stringify({ variants: updatedVariants }),
      });
      if (response.ok) {
        await fetchVariants();
        showSnackbar('Variant added successfully');
      } else {
        setVariantsError('Failed to add variant');
      }
    } catch (err) {
      setVariantsError(err.message || 'Failed to add variant');
    }
  };

  const handleUpdateVariant = async (updatedVariant) => {
    if (!mockItem?.id || !updatedVariant?.id) return;
    const updatedVariants = variants.map((v) =>
      v.id === updatedVariant.id ? updatedVariant : v
    );

    const endpoint = selectedTest
      ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}/variants?name=${encodeURIComponent(selectedTest.name)}`
      : `/api/v1/defaultmocks/${mockItem.id}/variants`;

    try {
      const response = await fetch(endpoint, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: FtJSON.stringify({ variants: updatedVariants }),
      });
      if (response.ok) {
        await fetchVariants();
        showSnackbar('Variant updated successfully');
      } else {
        setVariantsError('Failed to update variant');
      }
    } catch (err) {
      setVariantsError(err.message || 'Failed to update variant');
    }
  };

  const handleDeleteVariant = async (variant) => {
    if (!mockItem?.id || !variant?.id) return;
    const updatedVariants = variants.filter((v) => v.id !== variant.id);

    const endpoint = selectedTest
      ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}/variants?name=${encodeURIComponent(selectedTest.name)}`
      : `/api/v1/defaultmocks/${mockItem.id}/variants`;

    try {
      const response = await fetch(endpoint, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: FtJSON.stringify({ variants: updatedVariants }),
      });
      if (response.ok) {
        if (mockData.current_variant_id === variant.id) {
          const updatedMock = { ...mockData, current_variant_id: undefined };
          setMockData(updatedMock);
          const updateEndpoint = selectedTest
            ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}?name=${encodeURIComponent(selectedTest.name)}`
            : `/api/v1/defaultmocks/${mockItem.id}`;
          await fetch(updateEndpoint, {
            method: 'PUT',
            headers: {
              'Content-Type': 'application/json',
              Authorization: `Bearer ${localStorage.getItem('token')}`,
            },
            body: FtJSON.stringify(updatedMock),
          });
        }
        await fetchVariants();
        showSnackbar('Variant deleted successfully');
      } else {
        setVariantsError('Failed to delete variant');
      }
    } catch (err) {
      setVariantsError(err.message || 'Failed to delete variant');
    }
  };

  const handleSelectVariant = async (variant) => {
    const responseContent =
      typeof variant.response === 'string'
        ? variant.response
        : FtJSON.stringify(variant.response);
    const updatedMock = {
      ...mockData,
      response: { ...mockData.response, content: responseContent },
      current_variant_id: variant.id,
    };
    setMockData(updatedMock);

    const endpoint = selectedTest
      ? `/api/v1/tests/${selectedTest.id}/mockdata/${mockItem.id}?name=${encodeURIComponent(selectedTest.name)}`
      : `/api/v1/defaultmocks/${mockItem.id}`;
    try {
      const response = await fetch(endpoint, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: FtJSON.stringify(updatedMock),
      });
      if (response.ok) {
        showSnackbar('Response variant applied successfully');
      } else {
        showSnackbar('Failed to update mock with variant', 'error');
      }
    } catch (error) {
      showSnackbar('Error updating mock with variant', 'error');
    }
    setVariantsDialogOpen(false);
  };

  const handleDelete = (chipToDelete) => () => {
    const newChips = mockData.ignoreParams.filter(
      (chip) => chip !== chipToDelete
    );
    setMockData({ ...mockData, ignoreParams: newChips });
  };

  const addChip = (chip) => {
    if (chip && !mockData.ignoreParams?.includes(chip)) {
      setMockData({
        ...mockData,
        ignoreParams: [...(mockData.ignoreParams || []), chip],
      });
      setIpInputValue('');
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      addChip(ipInputValue.trim());
    }
  };

  const onInputChange = (e) => {
    const { name, value, checked } = e.target;
    setMockData((prev) => ({
      ...prev,
      [name]: name === 'waitForPrevious' ? checked : value,
    }));
  };

  const onWaitForChange = (event, newMockIds) => {
    setMockData({
      ...mockData,
      waitFor: newMockIds,
    });
  };

  const ignoreForAll = async (chip) => {
    const response = await fetch('/api/v1/ignoreForAll', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${localStorage.getItem('token')}`,
      },
      body: FtJSON.stringify(
        {
          param: chip,
          testName: selectedTest.name,
        },
        null,
        2
      ),
    });
    if (response.ok) {
      showSnackbar('Mock data updated successfully');
      onClose(true);
    } else {
      showSnackbar('Failed to update mock data', 'error');
    }
  };

  const duplicateMockData = async () => {
    const endpoint = selectedTest
      ? `/api/v1/tests/${selectedTest.id}/mockdata?name=${selectedTest.name}`
      : `/api/v1/defaultmocks`;
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: FtJSON.stringify(mockData, null, 2),
      });

      if (response.ok) {
        showSnackbar('Mock data duplicated successfully');
        onClose(true);
      } else {
        showSnackbar('Failed to duplicate mock data', 'error');
      }
    } catch (error) {
      console.error('Error updating mock data:', error);
      showSnackbar('Error updating mock data', 'error');
    }
  };

  const copyToDefaultMockData = async () => {
    const endpoint = `/api/v1/moveMockToDefaultMocks`;
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: FtJSON.stringify(
          { mockIds: [mockItem.id], testName: selectedTest.name },
          null,
          2
        ),
      });
      if (response.ok) {
        showSnackbar('Mock data sent to default mock data successfully');
      } else {
        showSnackbar('Failed to send mock data to default mock data', 'error');
      }
    } catch (error) {
      console.error('Error sending mock data to default mock data:', error);
      showSnackbar('Error sending mock data to default mock data', 'error');
    }
  };

  const copyDefaultMockToAllTests = async () => {
    const endpoint = `/api/v1/moveDefaultmocks`;
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        body: FtJSON.stringify({ mockIds: [mockItem.id] }, null, 2),
      });
      if (response.ok) {
        showSnackbar('Default mocks moved successfully');
      } else {
        showSnackbar('Failed to move default mocks', 'error');
      }
    } catch (error) {
      console.error('Error moving default mocks:', error);
      showSnackbar('Error moving default mocks', 'error');
    } finally {
      onClose();
    }
  };

  if (!mockItem) return null;

  const enableSendToDefaultMockData =
    !mockItem.isDuplicate &&
    selectedTest &&
    !isMockInDefaultMocks(defaultMocks, mockItem);

  const matchHeaderNames = parseMatchHeaderNames(envDetails?.MATCH_HEADERS);
  const mockRequestHeaders = mockData?.request?.headers || {};
  const mockResponseHeaders = mockData?.response?.headers || {};
  const responseContentType =
    getHeaderValueCaseInsensitive(mockResponseHeaders, 'content-type') ?? '';
  const responseContent = mockData?.response?.content ?? '';
  const missingMatchHeaders = matchHeaderNames.filter(
    (name) => getHeaderValueCaseInsensitive(mockRequestHeaders, name) === undefined
  );

  return (
    <Box
      sx={{
        minWidth: 700,
        p: 2,
        maxHeight: 'calc(100vh - 80px)',
        overflowY: 'scroll',
      }}
    >
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          mb: 2,
          alignItems: 'center',
        }}
      >
        <Typography variant="h5" gutterBottom>
          Mock Item Details
        </Typography>
        <Box>
          {selectedTest && (
            <IconButton id="mock-data-view-close-btn" onClick={onClose} aria-label="close">
              <CloseIcon />
            </IconButton>
          )}
          <Tooltip title="Delete">
            <IconButton id="mock-data-view-delete-btn" onClick={onDelete} aria-label="delete">
              <DeleteIcon color="secondary" />
            </IconButton>
          </Tooltip>
        </Box>
      </Box>
      <Divider />
      {matchHeaderNames.length > 0 && missingMatchHeaders.length > 0 && (
        <Alert severity="warning" sx={{ mt: 2, mb: 1 }}>
          Project MATCH_HEADERS requires these request headers on recordings:{' '}
          <strong>{missingMatchHeaders.join(', ')}</strong>. This mock does not
          include them in request headers, so it may never match live traffic.
        </Alert>
      )}
      <TextField
        id="mock-data-view-url"
        label="URL"
        fullWidth
        margin="normal"
        value={mockData.url}
        inputProps={{
          readOnly: true,
        }}
      />
      <TextField
        id="mock-data-view-method"
        label="Method"
        fullWidth
        margin="normal"
        value={mockData.method}
        inputProps={{
          readOnly: true,
        }}
      />
      <TextField
        id="mock-data-view-response-type"
        label="Response Type"
        fullWidth
        margin="normal"
        value={responseContentType}
        inputProps={{
          readOnly: true,
        }}
      />
      <TextField
        id="mock-data-view-delay"
        label="Delay (in milliseconds)"
        fullWidth
        margin="normal"
        value={mockData.delay}
        type="number"
        name="delay"
        onChange={onInputChange}
      />
      {selectedTest && (
        <FormControlLabel
          control={
            <Checkbox
              id="mock-data-view-wait-for-previous"
              checked={!!mockData.waitForPrevious}
              name="waitForPrevious"
              onChange={onInputChange}
            />
          }
          label="Wait for previous mock trigger"
        />
      )}
      {selectedTest && (
        <Autocomplete
          multiple
          freeSolo
          options={[]}
          name="waitFor"
          value={mockData.waitFor || []}
          onChange={onWaitForChange}
          onInputChange={(event, newInputValue, reason) => {
            if (reason === 'input' && newInputValue.includes(',')) {
              const mockIds = newInputValue
                .split(',')
                .map((p) => p.trim())
                .filter((p) => p.length > 0);
              const existingMockIds = mockData.waitFor || [];
              const newMockIds = [...existingMockIds, ...mockIds];
              onWaitForChange(event, newMockIds);
            }
          }}
          renderTags={(value, getTagProps) =>
            value.map((option, index) => (
              <Chip
                variant="outlined"
                label={option}
                {...getTagProps({ index })}
                key={index}
              />
            ))
          }
          renderInput={(params) => (
            <TextField
              id="mock-data-view-wait-for"
              name="waitFor"
              {...params}
              label="Wait for Mocks to be served"
              placeholder="Enter mock id, then press Enter"
              margin="normal"
              fullWidth
            />
          )}
        />
      )}

      <Box
        sx={{ width: '100%', display: 'flex', gap: 1, alignItems: 'center' }}
      >
        <Box>
          {mockData.ignoreParams?.map((chip, index) => (
            <Tooltip
              placement="right-start"
              title={
                <Box style={{ width: 200 }}>
                  Click below for to make {chip} as Ignore Parameter for all API
                  requests
                  <Box p={2}>
                    <Button
                      id={`mock-data-view-ignore-for-all-${chip}`}
                      variant="contained"
                      onClick={() => ignoreForAll(chip)}
                      size="small"
                      color="primary"
                    >
                      Ignore for all
                    </Button>
                  </Box>
                </Box>
              }
              arrow
            >
              <Chip
                key={index}
                label={chip}
                onDelete={handleDelete(chip)}
                sx={{ margin: '4px' }}
              />
            </Tooltip>
          ))}
        </Box>

        <TextField
          id="mock-data-view-ignore-params"
          value={ipInputValue}
          fullWidth
          onChange={(e) => setIpInputValue(e.target.value)}
          onKeyDown={handleKeyPress}
          placeholder="Type and press Enter or Comma"
          margin="normal"
          label="Ignore Parameters"
        />
      </Box>
      <TextField
        id="mock-data-view-mock-data"
        label="Mock Data"
        fullWidth
        multiline
        rows={8}
        margin="normal"
        value={responseContent}
        onChange={onContentChange}
        error={!isValidJSON(responseContent)}
        helperText={
          !isValidJSON(responseContent) ? 'Invalid JSON' : 'Valid JSON'
        }
      />
      <Box display="flex" gap={1} mb={2}>
        <Button
          id="mock-data-view-edit-with-ai-btn"
          variant="outlined"
          color="primary"
          startIcon={<AutoFixHighIcon />}
          onClick={() => setAiDialogOpen(true)}
        >
          Edit with AI
        </Button>
        <Button
          id="mock-data-view-response-variants-btn"
          variant="outlined"
          color="primary"
          startIcon={<AutoFixHighIcon />}
          onClick={handleOpenVariantsDialog}
        >
          Response Variants
        </Button>
      </Box>

      {mockData?.request?.postData?.text && (
        <TextField
          id="mock-data-view-post-data"
          label="Post Data"
          fullWidth
          multiline
          rows={8}
          margin="normal"
          value={
            mockData?.request?.postData?.mimeType === 'application/json'
              ? FtJSON.stringify(
                  FtJSON.parse(mockData?.request?.postData?.text),
                  null,
                  2
                )
              : mockData?.request?.postData?.text
          }
          onChange={onPostDataChange}
        />
      )}
      <TextField
        id="mock-data-view-full-mock-data"
        label="Full Mock Data"
        fullWidth
        multiline
        rows={8}
        margin="normal"
        value={mockDataString}
        onChange={onDataChange}
        error={!isValidJSON(mockDataString)}
        helperText={
          !isValidJSON(mockDataString) ? 'Invalid JSON' : 'Valid JSON'
        }
      />
      <Box display="flex" gap={1} justifyContent="space-between">
        <Box display="flex" gap={1}>
          <Button
            id="mock-data-view-update-btn"
            variant="contained"
            color="primary"
            onClick={onUpdate}
            style={{ marginTop: '16px' }}
            disabled={!isValidJSON(mockDataString)}
          >
            Update Mock Data
          </Button>
          <Button
            id="mock-data-view-duplicate-btn"
            variant="contained"
            color="primary"
            onClick={duplicateMockData}
            style={{ marginTop: '16px' }}
            disabled={!isValidJSON(mockDataString)}
          >
            Duplicate
          </Button>
        </Box>
        <Box display="flex" gap={1}>
          {mockItem.isDuplicate && (
            <Button
              id="mock-data-view-delete-all-duplicates-btn"
              variant="contained"
              color="secondary"
              onClick={deleteAllDuplicates}
              style={{ marginTop: '16px' }}
            >
              Delete All Duplicates
            </Button>
          )}
          {enableSendToDefaultMockData && (
            <Button
              id="mock-data-view-copy-to-default-btn"
              variant="contained"
              color="secondary"
              onClick={copyToDefaultMockData}
              style={{ marginTop: '16px' }}
            >
              Copy it to Default Mock Data
            </Button>
          )}
          {!enableSendToDefaultMockData && (
            <Button
              id="mock-data-view-copy-to-all-tests-btn"
              variant="contained"
              color="secondary"
              onClick={copyDefaultMockToAllTests}
              style={{ marginTop: '16px' }}
            >
              Copy it to All Tests
            </Button>
          )}
        </Box>
      </Box>
      <AiEditDialog
        open={aiDialogOpen}
        onClose={() => setAiDialogOpen(false)}
        mockData={responseContent}
        onSuccess={handleAiSuccess}
      />
      <ResponseVariantsDialog
        open={variantsDialogOpen}
        onClose={() => setVariantsDialogOpen(false)}
        mockItem={mockData}
        selectedTest={selectedTest}
        variants={variants}
        loading={variantsLoading}
        error={variantsError}
        onSelectVariant={handleSelectVariant}
        onRefresh={fetchVariants}
        onEnableVariants={handleEnableVariants}
        onAddVariant={handleAddVariant}
        onUpdateVariant={handleUpdateVariant}
        onDeleteVariant={handleDeleteVariant}
      />
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={6000}
        onClose={handleSnackbarClose}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert
          onClose={handleSnackbarClose}
          severity={snackbarSeverity}
          sx={{ width: '100%' }}
        >
          {snackbarMessage}
        </Alert>
      </Snackbar>
    </Box>
  );
};

MockDataView.propTypes = {
  onClose: PropTypes.func,
  mockItem: PropTypes.shape({
    url: PropTypes.string.isRequired,
    method: PropTypes.string.isRequired,
    response: PropTypes.shape({
      headers: PropTypes.shape({
        'content-type': PropTypes.string.isRequired,
      }).isRequired,
      content: PropTypes.string.isRequired,
    }).isRequired,
  }).isRequired,
  selectedTest: PropTypes.shape({
    id: PropTypes.string.isRequired,
  }),
  defaultMocks: PropTypes.array.isRequired,
  envDetails: PropTypes.object.isRequired,
};

MockDataView.defaultProps = {
  onClose: null,
  mockItem: {
    url: '',
    method: '',
    response: {
      headers: {
        'content-type': '',
      },
      content: '{}',
    },
  },
  selectedTest: null,
  defaultMocks: [],
  envDetails: null,
};

export default MockDataView;
