/* eslint-disable jsx-a11y/iframe-has-title */
import React, { useEffect, useState } from 'react';
import { Box } from '@mui/material';
import Button from '@mui/material/Button';
import TextField from '@mui/material/TextField';
import Typography from '@mui/material/Typography';
import Autocomplete from '@mui/material/Autocomplete';
import Chip from '@mui/material/Chip';
import IconButton from '@mui/material/IconButton';
import CloseIcon from '@mui/icons-material/Close';

const DefaultRecorder = ({ onClose }) => {
  const [isRecordingMockData, setIsRecordingMockData] = useState(false);
  const [isPlaywrightCodegenRunning, setIsPlaywrightCodegenRunning] =
    useState(false);
  const [error, setError] = useState(null);
  const [config, setConfig] = useState({
    url: '',
    patterns: ['^/api/.*'],
    testName: null,
    recordEvents: true,
  });

  const recordMockData = async () => {
    try {
      setIsRecordingMockData(true);
      const response = await fetch(`/api/v1/record/mocks`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(config),
      });
      if (!response.ok) {
        throw new Error('Failed to record mock data');
      }
    } catch (err) {
      setError(err.message);
      setIsRecordingMockData(false);
    }
  };

  const recordPlaywrightCodegenWithMocks = async () => {
    try {
      setIsPlaywrightCodegenRunning(true);
      setError(null);
      const response = await fetch(`/api/v1/record/playwright/mocks`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(config),
      });
      if (!response.ok) {
        throw new Error('Playwright codegen with mock recording failed');
      }
      onClose(null, {
        stopRecording: true,
      });
    } catch (err) {
      setError(err.message);
    } finally {
      setIsPlaywrightCodegenRunning(false);
    }
  };

  const onUrlChange = (event) => {
    setConfig({
      ...config,
      url: event.target.value,
    });
  };

  const onPatternsChange = (event, newPatterns) => {
    setConfig({
      ...config,
      patterns: newPatterns,
    });
  };

  const stopRecordingMockData = async () => {
    try {
      setIsRecordingMockData(false);
      const response = await fetch(`/api/v1/record`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error('Failed to stop recording mock data');
      }
      onClose(null, {
        stopRecording: true,
      });
    } catch (err) {
      setError(err.message);
    }
  };

  const fetchRecordingStatus = async () => {
    try {
      const response = await fetch(`/api/v1/record/status`);
      if (!response.ok) {
        throw new Error('Failed to fetch recording status');
      }
      const data = await response.json();
      setIsRecordingMockData(data.status === 'running');
    } catch (err) {
      console.error('Error fetching recording status:', err);
    }
  };

  const onCloseDrawer = () => {
    setIsRecordingMockData(false);
    setIsPlaywrightCodegenRunning(false);
    onClose();
  };

  useEffect(() => {
    const timeoutId = setTimeout(fetchRecordingStatus, 1000);
    return () => clearTimeout(timeoutId);
  }, []);

  return (
    <Box
      gap={1}
      display="flex"
      flexDirection="column"
      sx={{ width: '500px', margin: '0 auto', textAlign: 'left', mt: 4 }}
    >
      <Box
        sx={{ pl: 3, pr: 3, display: 'flex', justifyContent: 'space-between' }}
      >
        <Typography variant="h6" gutterBottom>
          Record Mock Data
        </Typography>
        <IconButton
          id="default-recorder-close-btn"
          color="primary"
          aria-label="record mock data"
          onClick={onCloseDrawer}
        >
          <CloseIcon />
        </IconButton>
      </Box>

      <Box
        width="100%"
        display="flex"
        flexDirection="row"
        gap={1}
        sx={{ mt: -2 }}
      >
        {!isRecordingMockData && !isPlaywrightCodegenRunning && (
          <Box
            p={3}
            sx={{ textAlign: 'center', border: '1px solid #333' }}
            width="100%"
            display="flex"
            flexDirection="column"
            gap={1}
          >
            <TextField
              id="default-recorder-url-input"
              label="URL"
              fullWidth
              margin="normal"
              value={config.url}
              onChange={onUrlChange}
            />
            <Autocomplete
              multiple
              freeSolo
              options={[]}
              value={config.patterns}
              onChange={onPatternsChange}
              onInputChange={(event, newInputValue, reason) => {
                if (reason === 'input' && newInputValue.includes(',')) {
                  const patterns = newInputValue
                    .split(',')
                    .map((p) => p.trim())
                    .filter((p) => p.length > 0);
                  const existingPatterns = config.patterns;
                  const newPatterns = [...existingPatterns, ...patterns];
                  onPatternsChange(event, newPatterns);
                }
              }}
              renderTags={(value, getTagProps) =>
                value.map((option, index) => (
                  <Chip
                    variant="outlined"
                    label={option}
                    {...getTagProps({ index })}
                    key={index}
                  />
                ))
              }
              renderInput={(params) => (
                <TextField
                  id="default-recorder-patterns-input"
                  {...params}
                  label="Patterns"
                  placeholder="Enter patterns separated by commas (e.g., ^/api/.*, ^/v1/.*)"
                  margin="normal"
                  fullWidth
                />
              )}
            />
            <Box
              display="flex"
              flexDirection="row"
              gap={1}
              flexWrap="wrap"
              justifyContent="center"
            >
              <Button
                id="default-recorder-record-btn"
                color="primary"
                onClick={recordMockData}
                variant="contained"
              >
                Record Mock Data
              </Button>
              <Button
                id="default-recorder-playwright-codegen-mocks-btn"
                color="secondary"
                onClick={recordPlaywrightCodegenWithMocks}
                variant="outlined"
              >
                Playwright codegen + mocks
              </Button>
            </Box>
          </Box>
        )}
        {isPlaywrightCodegenRunning && (
          <Box
            p={3}
            minWidth="100%"
            sx={{ textAlign: 'center', border: '1px solid #333' }}
            display="flex"
            flexDirection="column"
            gap={1}
          >
            <Typography>
              Playwright codegen with mock and event recording is running. Close
              the browser when you are done.
            </Typography>
          </Box>
        )}
        {isRecordingMockData && (
          <Box
            p={3}
            minWidth="100%"
            sx={{ textAlign: 'center', border: '1px solid #333' }}
            display="flex"
            flexDirection="column"
            gap={1}
          >
            <Typography>Recording in progress...</Typography>
            <Button
              id="default-recorder-stop-btn"
              color="primary"
              onClick={stopRecordingMockData}
              variant="contained"
            >
              Stop recording
            </Button>
          </Box>
        )}
      </Box>
      {error && <Typography color="error">{error}</Typography>}
    </Box>
  );
};

export default DefaultRecorder;
